-- =====================================================================
-- 02_budget_pcmn.sql : module Budget (structure PCMN de « creation budjet.xlsx »)
-- À exécuter UNE FOIS dans Supabase > SQL Editor, après 01_budget_analyse.sql
-- (réutilise is_admin(), can_read_finance(), can_write_budget() et set_updated_at()).
-- Idempotent : peut être relancé sans dommage (les données de départ ne sont insérées que si absentes).
-- =====================================================================

-- 1. Réalisé historique par compte (2023, 2024, 2025) : lecture seule dans l'application
create table if not exists public.pcmn_budget_history (
  account_key text    not null,           -- code PCMN à 6 chiffres (ou xNNN pour une ligne non codée du fichier)
  year        integer not null,
  amount      numeric(14,2) not null,
  primary key (account_key, year)
);

-- 2. Plan budgétaire annuel : un document JSON par année
--    data = { "v":1, "rows": { "<compte>": { "mode":"annual|monthly", "annual":0, "months":[12 nombres],
--                                           "subs":[{ "id","label","mode","annual","months" }] } } }
create table if not exists public.pcmn_budget_plans (
  year       integer primary key,
  data       jsonb        not null default '{"v":1,"rows":{}}'::jsonb,
  updated_at timestamptz  not null default now(),
  updated_by uuid         default auth.uid()
);

drop trigger if exists trg_pcmn_budget_plans_updated on public.pcmn_budget_plans;
create trigger trg_pcmn_budget_plans_updated before update on public.pcmn_budget_plans
  for each row execute function public.set_updated_at();

-- 3. Sécurité (RLS)
alter table public.pcmn_budget_history enable row level security;
alter table public.pcmn_budget_plans   enable row level security;

drop policy if exists pcmn_history_select on public.pcmn_budget_history;
drop policy if exists pcmn_history_write  on public.pcmn_budget_history;
create policy pcmn_history_select on public.pcmn_budget_history for select to authenticated using (public.can_read_finance());
create policy pcmn_history_write  on public.pcmn_budget_history for all    to authenticated using (public.is_admin()) with check (public.is_admin());

drop policy if exists pcmn_plans_select on public.pcmn_budget_plans;
drop policy if exists pcmn_plans_insert on public.pcmn_budget_plans;
drop policy if exists pcmn_plans_update on public.pcmn_budget_plans;
drop policy if exists pcmn_plans_delete on public.pcmn_budget_plans;
create policy pcmn_plans_select on public.pcmn_budget_plans for select to authenticated using (public.can_read_finance());
create policy pcmn_plans_insert on public.pcmn_budget_plans for insert to authenticated with check (public.can_write_budget());
create policy pcmn_plans_update on public.pcmn_budget_plans for update to authenticated using (public.can_write_budget()) with check (public.can_write_budget());
create policy pcmn_plans_delete on public.pcmn_budget_plans for delete to authenticated using (public.is_admin());

grant select on public.pcmn_budget_history to authenticated;
grant select, insert, update, delete on public.pcmn_budget_plans to authenticated;

-- 4. Réalisé 2023-2025 (tiré du fichier Excel ; les charges sont positives, les produits positifs)
on conflict (account_key, year) do nothing;

-- 5. Budget 2026 de départ : total annuel du fichier (colonne « Budget 2026 »), réparti par compte
--    (au prorata du réalisé 2025 quand le fichier ne détaille pas le compte). À ajuster dans l'application.
on conflict (year) do nothing;
